let mode=0,paused=matchMedia('(prefers-reduced-motion: reduce)').matches, rotation=.3,tilt=.3,targetRotation=.3,targetTilt=.3,burst=0,time=0,dragging=false,startX=0,startY=0,lastX=0,lastY=0,velocity=0;
