projected.sort((a,b)=>a.z-b.z);for(const p of projected){const opacity=.18+(p.z+1.5)/3.6*.72;ctx.fillStyle=`rgba(${color},${Math.min(.95,opacity)})`;const size=(mode===1?1.4:1.1)+(p.z+1.2)*.55;ctx.beginPath();ctx.arc(p.x,p.y,Math.max(.6,size),0,Math.PI*2);ctx.fill()}
