const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));window.addEventListener('scroll',()=>{const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('#progress').style.width=`${max>0?scrollY/max*100:0}%`},{passive:true});
document.querySelector('.waveform').innerHTML='';const projects=document.querySelector('.projects');let down=false,origin=0,scroll=0,moved=false;projects.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;down=true;moved=false;origin=e.clientX;scroll=projects.scrollLeft});window.addEventListener('pointermove',e=>{if(!down)return;const dx=e.clientX-origin;if(Math.abs(dx)>6){moved=true;projects.classList.add('dragging');projects.scrollLeft=scroll-dx}});window.addEventListener('pointerup',()=>{down=false;projects.classList.remove('dragging');setTimeout(()=>moved=false,0)});
